package com.aveycole.agentlooper;

import java.io.*;
import java.util.*;

/** Platform-independent, stereo floating-point engine. All clocks are sample clocks. */
public final class LoopEngine {
    public static final int RATE=48000, MAX_LAYERS=32, MAX_SECONDS=60;
    public final Bank[] banks={new Bank(),new Bank()};
    public volatile double bpm=120;
    public volatile int beats=4, bars=1, countIn=0;
    public volatile boolean click=false;
    public volatile String message="";
    public long clock;
    public volatile float inputPeak,outputPeak;
    public boolean limitOutput=true;
    private final float[] cleanA=new float[2], cleanB=new float[2];
    static final int GRAIN=2048,HOP=512;
    static final float[] WINDOW=new float[GRAIN];
    static {for(int i=0;i<GRAIN;i++)WINDOW[i]=(float)(.5-.5*Math.cos(2*Math.PI*i/GRAIN));}

    public static final class Layer {
        public final float[] audio;
        public final float[] envelope;
        public volatile String name;
        public long offset;
        public volatile int start,end,mode;
        public volatile double stretch=1,pitch=0,cutoff=20000,gain=1,pan=0;
        public volatile boolean mute,solo,reverse,expanded;
        double filter=1,l,r,gl,gr,wet;
        final double[] grainStarts=new double[4],grainRatios=new double[4];
        long lastGrain=Long.MIN_VALUE;int previousWarp,warpFade;
        public Layer(float[] a,String n,long at){this(a,n,at,null);}
        private Layer(float[] a,String n,long at,float[] peaks){audio=a;name=n;offset=at;end=a.length/2;if(peaks!=null){envelope=peaks;return;}envelope=new float[Math.min(1024,Math.max(1,end))];for(int i=0;i<end;i++){int k=(int)((long)i*envelope.length/Math.max(1,end));envelope[k]=Math.max(envelope[k],Math.max(Math.abs(a[i*2]),Math.abs(a[i*2+1])));}}
        public Layer copy(){Layer n=new Layer(audio,name,offset,envelope);n.start=start;n.end=end;n.mode=mode;n.stretch=stretch;n.pitch=pitch;n.cutoff=cutoff;n.gain=gain;n.pan=pan;n.mute=mute;n.solo=solo;n.reverse=reverse;return n;}
        public int frames(){return Math.max(1,(int)Math.round(Math.max(1,end-start)*stretch/(mode==1?Math.pow(2,pitch/12):1)));}
        public float peak(){float peak=0;for(float f:envelope)peak=Math.max(peak,f);return peak;}
        private double sample(double pos,int ch){int length=Math.max(1,end-start);pos=mod(pos,length);if(reverse)pos=length-1-pos;int i=(int)pos,j=(i+1)%length;double frac=pos-i;double a=read(start+i,ch),b=read(start+j,ch);return a+(b-a)*frac;}
        private float read(int p,int ch){return p>=0&&p<audio.length/2?audio[p*2+ch]:0;}
        private double edge(double pos,int ch){int length=Math.max(1,end-start),fade=Math.min(160,length/4);pos=mod(pos,length);if(fade==0||pos>=fade&&pos<length-fade)return sample(pos,ch);double tail,head,x;if(pos<fade){tail=length-1-pos;head=pos;x=(pos+fade)/(2*fade);}else{double d=length-pos;tail=pos;head=d-1;x=(fade-d)/(2*fade);}double w=.5-.5*Math.cos(Math.PI*x);return sample(tail,ch)*(1-w)+sample(head,ch)*w;}
        private double granular(long frame,int ch,double ratio,double timeStretch){double v=0;long hop=Math.floorDiv(frame,HOP);if(lastGrain==Long.MIN_VALUE||hop<lastGrain||hop-lastGrain>4)lastGrain=hop-4;while(lastGrain<hop){long next=lastGrain+1;int slot=Math.floorMod(next,4),prev=Math.floorMod(next-1,4);double wanted=next*HOP/timeStretch+(1/timeStretch-ratio)*GRAIN/2.0,best=wanted,bestError=Double.MAX_VALUE;if(next>hop-3){for(int shift=-256;shift<=256;shift+=4){double candidate=wanted+shift,error=0;for(int j=0;j<192;j+=8){double ref=sample(grainStarts[prev]+(HOP+j)*grainRatios[prev],0),value=sample(candidate+j*ratio,0),d=ref-value;error+=d*d;}error+=Math.abs(shift)*.00000001;if(error<bestError){bestError=error;best=candidate;}}}grainStarts[slot]=best;grainRatios[slot]=ratio;lastGrain=next;}for(int k=0;k<4;k++){long anchor=(hop-k)*HOP;int age=(int)(frame-anchor),slot=Math.floorMod(hop-k,4);v+=edge(grainStarts[slot]+age*grainRatios[slot],ch)*WINDOW[age]*.5;}return v;}
        void mix(long frame,boolean audible,float[] out,int warpFrames,long warpOrigin){double timeStretch=warpFrames>0?warpFrames/(double)Math.max(1,end-start):stretch;boolean independent=warpFrames>0||mode==0;double target=audible?gain:0;gl+=(target*Math.min(1,1-pan)-gl)*.004;gr+=(target*Math.min(1,1+pan)-gr)*.004;long phase=warpFrames>0?(long)mod(frame-warpOrigin,warpFrames):frame-offset;double pos=phase/timeStretch*(!independent?Math.pow(2,pitch/12):1);double sl=edge(pos,0),sr=edge(pos,1);double targetWet=independent&&(Math.abs(pitch)>.001||Math.abs(timeStretch-1)>.001)?1:0;wet+=(targetWet-wet)*.004;if(wet>.00001){double ratio=Math.pow(2,pitch/12);sl=sl*(1-wet)+granular(phase,0,ratio,timeStretch)*wet;sr=sr*(1-wet)+granular(phase,1,ratio,timeStretch)*wet;}if(previousWarp!=warpFrames){previousWarp=warpFrames;warpFade=240;lastGrain=Long.MIN_VALUE;}if(warpFade>0){double blend=1-warpFade/240.0;sl=l*(1-blend)+sl*blend;sr=r*(1-blend)+sr*blend;warpFade--;}double alpha=cutoff>=19999?1:1-Math.exp(-2*Math.PI*cutoff/RATE);filter+=(alpha-filter)*.02;l+=filter*(sl-l);r+=filter*(sr-r);out[0]+=l*gl;out[1]+=r*gr;}
    }
    public static final class Bank {
        public final ArrayList<Layer> layers=new ArrayList<>();
        public boolean playing=true,auto=false,sync=false,waitInput,signalArmed;public double triggerDb=-40;
        public int quantize=0,inputMode=0;
        public long frame,origin,armedAt=-1,playAt=-1;
        public int period,warpFrames;public boolean warp,warpPending;long warpAt;
        public boolean recording,overdub,waiting;
        private float[] take;
        private int written,limit;
        private long takeOffset;
        private int cyclePeriod;
        public int cycle(){return warp?warpFrames:layers.isEmpty()?period:layers.get(0).frames();}
        public String state(){return signalArmed?"WAIT INPUT":waiting?"ARMED":recording?"REC":String.format(Locale.US,"%.2f s",cycle()/(double)RATE);}
    }
    public static double mod(double p,double n){return (p%n+n)%n;}
    public int measure(){return (int)Math.round(RATE*60/bpm*beats);}
    public synchronized void begin(int index,boolean overdub){Bank b=banks[index];if(b.recording){finish(index,!b.overdub);return;}if(overdub&&b.layers.isEmpty()){message="Record a loop first";return;}if(b.layers.size()>=MAX_LAYERS){message="Layer limit reached";return;}b.overdub=overdub;b.limit=overdub?b.cycle():b.sync?Math.min(RATE*MAX_SECONDS,measure()*bars):RATE*MAX_SECONDS;if(!memoryFor(b.limit)){message="Memory limit — export and remove layers";return;}b.take=new float[b.limit*2];b.written=0;b.recording=true;b.waiting=true;b.cyclePeriod=b.cycle();b.signalArmed=b.waitInput;if(b.signalArmed){b.armedAt=Long.MAX_VALUE;message="";return;}long delay=(long)countIn*measure();b.armedAt=clock+delay;
        Bank peer=banks[1-index];Bank reference=b.quantize==2?peer:(overdub&&b.quantize==1?(index==1&&!banks[0].layers.isEmpty()?banks[0]:b):null);
        if(reference!=null){if(reference.cycle()==0){cancel(b);message="Record a reference loop first";return;}b.armedAt=reference==b&&!b.playing?clock+delay:nextBoundary(reference,clock+delay);}else if(b.quantize==1)b.armedAt=((clock+delay+measure()-1)/measure())*measure();b.takeOffset=b.frame+Math.max(0,b.armedAt-clock);if(!b.playing&&b.quantize==0)b.playing=true;message="";}
    boolean memoryFor(int frames){Runtime r=Runtime.getRuntime();return r.maxMemory()-(r.totalMemory()-r.freeMemory())>(long)frames*16+8*1024*1024;}
    long nextBoundary(Bank ref,long earliest){if(!ref.playing)return Long.MAX_VALUE;long phase=(long)mod(ref.frame-ref.origin,ref.cycle());long at=clock+ref.cycle()-phase;if(at<earliest)at+=((earliest-at+ref.cycle()-1)/ref.cycle())*ref.cycle();return at;}
    private void cancel(Bank b){b.signalArmed=false;b.recording=b.waiting=false;b.take=null;b.written=0;b.armedAt=-1;}
    private void addTake(Bank b){if(b.written<480)return;float[] audio=b.written*2==b.take.length?b.take:Arrays.copyOf(b.take,b.written*2);Layer l=new Layer(audio,"Layer "+(b.layers.size()+1),b.takeOffset);b.layers.add(l);if(b.layers.size()==1){b.period=b.written;b.origin=b.takeOffset;}}
    public synchronized void finish(int index,boolean continueAuto){Bank b=banks[index];if(!b.recording)return;boolean go=continueAuto&&b.auto&&!b.overdub&&!b.signalArmed;addTake(b);cancel(b);if(go&&!b.layers.isEmpty()){int q=b.quantize,ci=countIn;boolean wait=b.waitInput;b.waitInput=false;b.quantize=0;countIn=0;begin(index,true);b.quantize=q;countIn=ci;b.waitInput=wait;}}
    public synchronized void stop(int index){Bank b=banks[index];finish(index,false);if(b.playAt>=0){b.playAt=-1;return;}if(b.playing){b.playing=false;return;}if(b.quantize==0){b.playing=true;return;}Bank peer=banks[1-index];b.playAt=b.quantize==2?nextBoundary(peer,clock):((clock+measure())/measure())*measure();if(b.quantize==2&&peer.cycle()==0){b.playAt=-1;message="Record a reference loop first";}}
    public synchronized void undo(int index){Bank b=banks[index];if(b.recording){finish(index,false);return;}if(!b.layers.isEmpty())b.layers.remove(b.layers.size()-1);if(b.layers.isEmpty()){b.period=0;b.origin=b.frame;b.warp=b.warpPending=false;}}
    public synchronized LoopEngine snapshot(){LoopEngine e=new LoopEngine();e.bpm=bpm;e.beats=beats;e.bars=bars;e.countIn=countIn;e.click=click;for(int i=0;i<2;i++){Bank a=banks[i],b=e.banks[i];b.auto=a.auto;b.sync=a.sync;b.waitInput=a.waitInput;b.triggerDb=a.triggerDb;b.warp=a.warp;b.warpFrames=a.warpFrames;b.quantize=a.quantize;b.inputMode=a.inputMode;b.frame=a.frame;b.origin=a.origin;b.period=a.period;for(int j=0;j<a.layers.size();j++)b.layers.add(a.layers.get(j).copy());}return e;}
    public synchronized void toggleWarp(int index){Bank b=banks[index];if(b.warpPending){b.warpPending=false;return;}if(b.warp){b.warp=false;return;}if(b.layers.isEmpty()){message="Record a loop first";return;}if(b.recording)finish(index,false);b.warpFrames=b.cycle();if(!b.playing){b.warp=true;return;}b.warpAt=b.frame+(long)(b.warpFrames-mod(b.frame-b.origin,b.warpFrames));b.warpPending=true;}
    public synchronized void remove(int index,Layer l){Bank b=banks[index];b.layers.remove(l);if(b.layers.isEmpty()){b.period=0;b.warp=b.warpPending=false;}}
    private void capture(Bank b,float l,float r){if(!b.recording||b.waiting)return;b.take[b.written*2]=l;b.take[b.written*2+1]=r;b.written++;if(b.written==b.limit){addTake(b);if(b.auto&&b.layers.size()<MAX_LAYERS&&memoryFor(b.cycle())){b.overdub=true;b.limit=b.cycle();b.takeOffset=b.frame+1;if(!memoryFor(b.limit)){message="Memory limit — export and remove layers";return;}b.take=new float[b.limit*2];b.written=0;}else{cancel(b);if(b.layers.size()>=MAX_LAYERS)message="Layer limit reached";}}}
    private void observeInput(int index,float l,float r){Bank b=banks[index];if(!b.signalArmed||Math.max(Math.abs(l),Math.abs(r))<Math.pow(10,b.triggerDb/20))return;b.signalArmed=false;long delay=(long)countIn*measure();b.armedAt=clock+delay;Bank peer=banks[1-index],reference=b.quantize==2?peer:b.overdub&&b.quantize==1?(index==1&&!banks[0].layers.isEmpty()?banks[0]:b):null;if(reference!=null)b.armedAt=reference==b&&!b.playing?clock+delay:nextBoundary(reference,clock+delay);else if(b.quantize==1)b.armedAt=((clock+delay+measure()-1)/measure())*measure();if(!b.playing&&b.quantize==0)b.playing=true;}
    private void schedules(int i){Bank b=banks[i];if(b.warpPending&&(!b.playing||b.frame>=b.warpAt)){b.warp=true;b.warpPending=false;}if(b.playAt==Long.MAX_VALUE){Bank peer=banks[1-i];if(peer.playing&&peer.cycle()>0)b.playAt=nextBoundary(peer,clock);}if(b.playAt>=0&&clock>=b.playAt){b.frame=b.origin;b.playing=true;b.playAt=-1;}if(b.recording&&b.waiting&&!b.signalArmed){if(b.armedAt==Long.MAX_VALUE){Bank ref=b.quantize==2?banks[1-i]:(i==1&&banks[0].cycle()>0?banks[0]:b);if(ref.playing)b.armedAt=nextBoundary(ref,clock+(long)countIn*measure());}if(clock>=b.armedAt){b.waiting=false;if(!b.playing){b.frame=b.origin;b.playing=true;}b.takeOffset=b.frame;}}}
    private void render(Bank b,float[] out){out[0]=out[1]=0;boolean solo=false;for(Layer l:b.layers)solo|=l.solo;for(Layer l:b.layers)l.mix(b.frame,b.playing&&!l.mute&&(!solo||l.solo),out,b.warp?b.warpFrames:0,b.origin);}
    public synchronized void process(float[] input,int channels,int left,int right,float[] output,int frames){float inPeak=0,outPeak=0;for(int f=0;f<frames;f++){float il=input==null?0:input[f*channels+left],ir=input==null?0:input[f*channels+right];inPeak=Math.max(inPeak,Math.max(Math.abs(il),Math.abs(ir)));Bank a=banks[0],b=banks[1];observeInput(0,il,ir);schedules(0);capture(a,il,ir);render(a,cleanA);float bl=b.inputMode==1?cleanA[0]:b.inputMode==2?il+cleanA[0]:il,br=b.inputMode==1?cleanA[1]:b.inputMode==2?ir+cleanA[1]:ir;observeInput(1,bl,br);schedules(1);capture(b,bl,br);render(b,cleanB);double tick=0;boolean cue=false;long age=0;for(Bank bank:banks)if(bank.recording){if(bank.waiting&&!bank.signalArmed&&bank.armedAt!=Long.MAX_VALUE&&countIn>0&&clock>=bank.armedAt-(long)countIn*measure()){cue=true;age=clock-(bank.armedAt-(long)countIn*measure());break;}if(!bank.waiting&&click){cue=true;age=clock-bank.armedAt;break;}}if(cue){double beatFrames=RATE*60/bpm;long beat=(long)(age/beatFrames);double t=age-Math.round(beat*beatFrames);if(t>=0&&t<1440)tick=.1*Math.sin(2*Math.PI*(beat%beats==0?1500:1000)*t/RATE)*Math.min(1,t/48)*Math.exp(-t/300);}float ol=(float)(cleanA[0]+cleanB[0]+tick),or=(float)(cleanA[1]+cleanB[1]+tick);outPeak=Math.max(outPeak,Math.max(Math.abs(ol),Math.abs(or)));output[f*2]=limitOutput?Math.max(-1,Math.min(1,ol)):ol;output[f*2+1]=limitOutput?Math.max(-1,Math.min(1,or)):or;if(a.playing)a.frame++;if(b.playing)b.frame++;clock++;}inputPeak=inPeak;outputPeak=outPeak;}

    public synchronized void save(OutputStream stream)throws IOException{DataOutputStream d=new DataOutputStream(new BufferedOutputStream(stream));d.writeInt(0x41474c34);d.writeDouble(bpm);d.writeInt(beats);d.writeInt(bars);d.writeInt(countIn);d.writeBoolean(click);for(Bank b:banks){d.writeBoolean(b.auto);d.writeBoolean(b.sync);d.writeBoolean(b.waitInput);d.writeDouble(b.triggerDb);d.writeBoolean(b.warp);d.writeInt(b.warpFrames);d.writeInt(b.quantize);d.writeInt(b.inputMode);d.writeLong(b.frame);d.writeLong(b.origin);d.writeInt(b.layers.size());for(Layer l:b.layers){d.writeUTF(l.name);d.writeLong(l.offset);d.writeInt(l.start);d.writeInt(l.end);d.writeDouble(l.stretch);d.writeDouble(l.pitch);d.writeDouble(l.cutoff);d.writeDouble(l.gain);d.writeDouble(l.pan);d.writeBoolean(l.mute);d.writeBoolean(l.solo);d.writeBoolean(l.reverse);d.writeInt(l.mode);d.writeInt(l.audio.length);for(float f:l.audio)d.writeFloat(f);}}d.flush();}
    public synchronized void load(InputStream stream)throws IOException{DataInputStream d=new DataInputStream(new BufferedInputStream(stream));int version=d.readInt();if(version!=0x41474c32&&version!=0x41474c33&&version!=0x41474c34)throw new IOException("Invalid session");double tempo=d.readDouble();int meter=d.readInt(),nbars=d.readInt(),ci=d.readInt();boolean met=d.readBoolean();Bank[] loaded={new Bank(),new Bank()};for(Bank b:loaded){b.auto=d.readBoolean();b.sync=d.readBoolean();b.waitInput=version>=0x41474c33&&d.readBoolean();b.triggerDb=version>=0x41474c33?d.readDouble():-40;if(!Double.isFinite(b.triggerDb)||b.triggerDb< -72||b.triggerDb> -6)throw new IOException("Invalid trigger threshold");if(version>=0x41474c34){b.warp=d.readBoolean();b.warpFrames=d.readInt();if(b.warp&&(b.warpFrames<1||b.warpFrames>RATE*MAX_SECONDS*4))throw new IOException("Invalid warp cycle");}b.quantize=d.readInt();b.inputMode=d.readInt();if(b.quantize<0||b.quantize>2||b.inputMode<0||b.inputMode>2)throw new IOException("Invalid routing");b.frame=d.readLong();b.origin=d.readLong();int count=d.readInt();if(count<0||count>MAX_LAYERS)throw new IOException("Invalid layer count");for(int i=0;i<count;i++){String n=d.readUTF();long at=d.readLong();int start=d.readInt(),end=d.readInt();double stretch=d.readDouble(),pitch=d.readDouble(),cutoff=d.readDouble(),gain=d.readDouble(),pan=d.readDouble();boolean mute=d.readBoolean(),solo=d.readBoolean(),rev=d.readBoolean();int mode=d.readInt();int length=d.readInt();if(mode<0||mode>1||length<2||length>RATE*MAX_SECONDS*2||length%2!=0||start<0||end<=start||end>length||!Double.isFinite(stretch)||stretch<.5||stretch>2||!Double.isFinite(pitch)||Math.abs(pitch)>12||!Double.isFinite(cutoff)||cutoff<40||cutoff>20000||!Double.isFinite(gain)||gain<0||gain>1.5||!Double.isFinite(pan)||Math.abs(pan)>1)throw new IOException("Invalid layer");float[] data=new float[length];for(int j=0;j<length;j++){data[j]=d.readFloat();if(!Float.isFinite(data[j]))throw new IOException("Invalid sample");}Layer l=new Layer(data,n,at);l.start=start;l.end=end;l.mode=mode;l.stretch=stretch;l.pitch=pitch;l.cutoff=cutoff;l.gain=gain;l.pan=pan;l.mute=mute;l.solo=solo;l.reverse=rev;b.layers.add(l);}b.period=b.cycle();b.playing=false;}if(!Double.isFinite(tempo)||tempo<20||tempo>300||meter<2||meter>7||nbars<1||nbars>16||ci<0||ci>2)throw new IOException("Invalid timing");bpm=tempo;beats=meter;bars=nbars;countIn=ci;click=met;banks[0]=loaded[0];banks[1]=loaded[1];clock=0;}
}
